(7005611, 1059424, 124982, '<td valign="top">I wonder if this is a <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_N.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_N.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_N.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=113156" rel="nofollow" target="_blank">jagar</a> image. The loneliness of the pigeon amongst the empty stools tells quite the story.</td>', 'I wonder if this is a  jagar image. The loneliness of the pigeon amongst the empty stools tells quite the story.', '2013-03-23 21:57:14.000000', NULL, 1),
(7005622, 1058796, 96751, '<td valign="top">Love it</td>', 'Love it', '2013-03-23 22:22:36.000000', NULL, 1),
(7005624, 1059311, 96751, '<td valign="top">One of the more inventive image in the challenge, John. I do hope this is doing well for you. And killer title :-)</td>', 'One of the more inventive image in the challenge, John. I do hope this is doing well for you. And killer title :-)', '2013-03-23 22:23:14.000000', NULL, 1),
(7005625, 1059260, 96751, '<td valign="top">I really like this. The contrast of textures between the dried and crinkled buds and the smooth hands is very appealing. A slight nit is that the vignetting is spilling on the the fingertips, making them look dirty.</td>', 'I really like this. The contrast of textures between the dried and crinkled buds and the smooth hands is very appealing. A slight nit is that the vignetting is spilling on the the fingertips, making them look dirty.', '2013-03-23 22:25:18.000000', NULL, 1),
(7005626, 1059366, 96751, '<td valign="top">A lynch mob!  Gorgeous b/w, perfect tones across the range, and the backdrop textures are very complimentary. Perfectly anthropomorphic image. Just because she''s got a thing for pears, this reminds me of Wendy''s work.</td>', 'A lynch mob!  Gorgeous b/w, perfect tones across the range, and the backdrop textures are very complimentary. Perfectly anthropomorphic image. Just because she''s got a thing for pears, this reminds me of Wendy''s work.', '2013-03-23 22:29:43.000000', NULL, 1),
(7005627, 1059255, 96751, '<td valign="top">I wish there were more context in the setting. The basket looks like it''s floating in the inky blackness...</td>', 'I wish there were more context in the setting. The basket looks like it''s floating in the inky blackness...', '2013-03-23 22:31:06.000000', NULL, 1),
(7005628, 1059270, 96751, '<td valign="top">A cool idea. You clearly went to some trouble to round up the socks and lay them out</td>', 'A cool idea. You clearly went to some trouble to round up the socks and lay them out', '2013-03-23 22:32:00.000000', NULL, 1),
(7005629, 1058803, 96751, '<td valign="top">This gorgeous creature looks oversharpened to me</td>', 'This gorgeous creature looks oversharpened to me', '2013-03-23 22:32:27.000000', NULL, 1),
(7005630, 1058900, 96751, '<td valign="top">I am most impressed with the speed with which you must have hit that shutter :-)</td>', 'I am most impressed with the speed with which you must have hit that shutter :-)', '2013-03-23 22:32:56.000000', NULL, 1),
(7005631, 1059257, 96751, '<td valign="top">Wonderful balancing act. I like the clean tones. And I miss those milk bottles</td>', 'Wonderful balancing act. I like the clean tones. And I miss those milk bottles', '2013-03-23 22:34:37.000000', NULL, 1),
(7005632, 1059297, 96751, '<td valign="top">I love everything about this image but the crop. It makes the image look unbalanced to me.</td>', 'I love everything about this image but the crop. It makes the image look unbalanced to me.', '2013-03-23 22:36:31.000000', NULL, 1),
(7005633, 1059294, 96751, '<td valign="top">Thirteen....?<br/> <br/>But they''re precious</td>', 'Thirteen....? But they''re precious', '2013-03-23 22:36:58.000000', NULL, 1),
(7005634, 1058801, 96751, '<td valign="top">How did you get such clarity?????</td>', 'How did you get such clarity?????', '2013-03-23 22:39:29.000000', NULL, 1),
(7005635, 1058992, 96751, '<td valign="top">I love it!!! All the lines make my eyes a bit crazy, but it all works. I''m not sure, but I think a square crop would make it even better.</td>', 'I love it!!! All the lines make my eyes a bit crazy, but it all works. I''m not sure, but I think a square crop would make it even better.', '2013-03-23 22:40:36.000000', NULL, 1),
(7005636, 1059249, 96751, '<td valign="top">I really love how the smoke trails are all converging in the middle, Brennan.</td>', 'I really love how the smoke trails are all converging in the middle, Brennan.', '2013-03-23 22:44:10.000000', NULL, 1),
(7005637, 1059202, 96751, '<td valign="top">Ohhhhhhhhh. I think this might be my favorite. The color of the flowers is perfect, and that is the most incredible bokeh EVER.</td>', 'Ohhhhhhhhh. I think this might be my favorite. The color of the flowers is perfect, and that is the most incredible bokeh EVER.', '2013-03-23 22:45:14.000000', NULL, 1);
